<?php
namespace App\Services;
class JobQualityAnalyzer{public function analyze(array $data):array{$score=100;$issues=[];$check=function(bool $condition,int $penalty,string $message)use(&$score,&$issues){if(!$condition){$score-=$penalty;$issues[]=$message;}};$check(mb_strlen(trim($data['title']))>=5,15,'Utiliza un título de puesto claro y específico.');$check(mb_strlen(trim($data['description']))>=200,20,'Amplía la descripción a por lo menos 200 caracteres.');$check(count($data['requirements'])>=3,15,'Incluye al menos tres requisitos relevantes.');$check(count($data['benefits'])>=1,10,'Agrega al menos un beneficio para candidatos.');$check(filled($data['location']),10,'Indica la ubicación de la vacante.');$check(filled($data['salary_min'])&&filled($data['salary_max']),10,'Publicar un rango salarial mejora la transparencia.');$check(!filled($data['salary_min'])||!filled($data['salary_max'])||$data['salary_min']<=$data['salary_max'],20,'El salario mínimo no puede superar el máximo.');return ['score'=>max(0,$score),'issues'=>$issues];}}
